if(id==='calculator'){let expr='',d=root.querySelector('#calc-display');root.querySelectorAll('[data-calc]').forEach(b=>b.onclick=()=>{let v=b.dataset.calc;if(v==='C')expr='';else if(v==='⌫')expr=expr.slice(0,-1);else if(v==='±')expr='-'+expr;else if(v==='1/x')expr='1/('+expr+')';else if(v==='x²')expr+='**2';else if(v==='='){try{let e=expr.replaceAll('×','*').replaceAll('÷','/').replaceAll('π','Math.PI').replaceAll('√(','Math.sqrt(').replace(/(sin|cos|tan)\(/g,'Math.$1(');if(root.querySelector('#calc-angle').value==='DEG')e=e.replace(/Math\.(sin|cos|tan)\(([^()]*)\)/g,'Math.$1(($2)*Math.PI/180)');if(!/^[0-9+*/().,%\sMathPIe-]+$/.test(e))throw 0;expr=String(Function('return ('+e+')')());if(!Number.isFinite(+expr))throw 0}catch{expr='Error'}}else expr+=v;d.value=expr||'0'})}
if(id==='games'){let game='2048',board=[],cards=[],turn='X',cells=[];const stage=root.querySelector('#game-stage');function start(){if(game==='2048'){board=Array(16).fill(0);spawn();spawn()}else if(game==='memory'){let a=['🍎','🍋','🍇','🍒','⭐','🌙','⚽','🎈'];cards=[...a,...a].sort(()=>Math.random()-.5).map(v=>({v,open:false,done:false}))}else{cells=Array(9).fill('');turn='X'}draw()}function spawn(){let f=board.map((v,i)=>v?null:i).filter(v=>v!==null);if(f.length)board[f[Math.random()*f.length|0]]=Math.random()<.9?2:4}function draw(){if(game==='2048')stage.innerHTML='<p>Score: '+board.reduce((a,b)=>a+b,0)+'</p><div class="g2048">'+board.map((v,i)=>'<button data-i="'+i+'">'+(v||'')+'</button>').join('')+'</div>';else if(game==='memory')stage.innerHTML='<div class="memory-grid">'+cards.map((v,i)=>'<button data-m="'+i+'">'+(v.open||v.done?v.v:'?')+'</button>').join('')+'</div>';else stage.innerHTML='<div class="ttt-grid">'+cells.map((v,i)=>'<button data-t="'+i+'">'+v+'</button>').join('')+'</div><p>Turn: '+turn+'</p>';stage.querySelectorAll('[data-i]').forEach(b=>b.onclick=()=>{let i=+b.dataset.i;if(board[i])return;board[i]=2;spawn();draw()});stage.querySelectorAll('[data-m]').forEach(b=>b.onclick=()=>{let c=cards[+b.dataset.m];if(c.open||c.done)return;c.open=true;draw();let o=cards.filter(x=>x.open&&!x.done);if(o.length===2){if(o[0].v===o[1].v)o.forEach(x=>x.done=true);else setTimeout(()=>{o.forEach(x=>x.open=false);draw()},700)}});stage.querySelectorAll('[data-t]').forEach(b=>b.onclick=()=>{let i=+b.dataset.t;if(cells[i])return;cells[i]=turn;turn=turn==='X'?'O':'X';draw()})}root.querySelectorAll('[data-game]').forEach(b=>b.onclick=()=>{game=b.dataset.game;start()});start()}
if(id==='notes'){const list=root.querySelector('#notes-list');const draw=()=>{list.innerHTML=notes.map((n,i)=>'<article class="note-card"><input data-title="'+i+'" value="'+n.title.replaceAll('"','&quot;')+'"><textarea data-body="'+i+'">'+n.body.replaceAll('<','&lt;')+'</textarea><button data-delete="'+i+'">Delete</button></article>').join('')||'<p class="muted">No notes yet.</p>';list.querySelectorAll('input,textarea').forEach(el=>el.oninput=()=>{let i=+(el.dataset.title??el.dataset.body);if(el.dataset.title!==undefined)notes[i].title=el.value;else notes[i].body=el.value;localStorage.setItem('myos-notes',JSON.stringify(notes))});list.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{notes.splice(+b.dataset.delete,1);localStorage.setItem('myos-notes',JSON.stringify(notes));draw()})};root.querySelector('#new-note').onclick=()=>{notes.unshift({title:'New note',body:''});localStorage.setItem('myos-notes',JSON.stringify(notes));draw()};draw()}
if(id==='browser'){let history=[],historyAt=-1;const frame=root.querySelector('#browser-frame'),address=root.querySelector('#browser-url'),empty=root.querySelector('#browser-empty'),status=root.querySelector('#browser-status-text');function showPage(url,srcdoc,record=true){if(record){history=history.slice(0,historyAt+1);history.push({url,srcdoc:srcdoc||null});historyAt=history.length-1}empty.hidden=true;status.textContent=srcdoc?'Local preview':url;address.value=url;if(srcdoc!==undefined&&srcdoc!==null){frame.removeAttribute('src');frame.srcdoc=srcdoc}else{frame.srcdoc='';frame.src=url}root.querySelector('#browser-back').disabled=historyAt<=0;root.querySelector('#browser-forward').disabled=historyAt>=history.length-1}function go(){let value=address.value.trim();if(!value)return;let lower=value.toLowerCase(),url;if(lower.startsWith('http://')||lower.startsWith('https://'))url=value;else if(value.includes('.')&&!value.includes(' '))url='https://'+value;else url='https://www.google.com/search?q='+encodeURIComponent(value);showPage(url,null)}root.querySelector('#browser-form').onsubmit=e=>{e.preventDefault();go()};root.querySelector('#browser-back').onclick=()=>{if(historyAt>0){historyAt--;let p=history[historyAt];showPage(p.url,p.srcdoc,false)}};root.querySelector('#browser-forward').onclick=()=>{if(historyAt<history.length-1){historyAt++;let p=history[historyAt];showPage(p.url,p.srcdoc,false)}};root.querySelector('#browser-reload').onclick=()=>{let p=history[historyAt];if(p)showPage(p.url,p.srcdoc,false)};root.querySelector('#browser-home').onclick=()=>{frame.src='about:blank';frame.srcdoc='';address.value='';empty.hidden=false;status.textContent='Ready';history=[];historyAt=-1;root.querySelector('#browser-back').disabled=true;root.querySelector('#browser-forward').disabled=true}}
